#!/usr/bin/env bash
set -euo pipefail


REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO_DIR"

PYTHON="${WORLDTS_PYTHON:-python}"
GPU="${GPU:-0}"
export WORLDTS_NUMERIC_DATA="${WORLDTS_NUMERIC_DATA:-$REPO_DIR/dataset/forecasting}"

run() {
    if [[ "${DRY_RUN:-0}" == "1" ]]; then
        printf 'WORLDTS_NUMERIC_DATA=%q ' "$WORLDTS_NUMERIC_DATA"
        printf '%q ' "$@"
        printf '\n'
        return 0
    fi
    "$@"
}

